@csrf_exempt
@require_safe
def api_me(request):
    auth = _authenticate_api(request)
    if auth is None:
        return _api_error("Unauthorized", 401)
    user, scope = auth
    return JsonResponse({
        "email": user.email, "role": user.role, "display_name": user.display_name,
        "scope": scope,
    })

@csrf_exempt
@require_safe
def api_courses(request):
    auth = _authenticate_api(request)
    if auth is None:
        return _api_error("Unauthorized", 401)
    user, scope = auth
    # Respect role boundaries: students only see their enrolled courses; staff only
    # courses they teach/assist. Admins see all.
    if user.is_school_admin:
        qs = Course.objects.all()
    elif user.is_instructor or user.is_teaching_assistant:
        qs = Course.objects.filter(Q(instructors=user) | Q(assistants=user)).distinct()
    elif user.is_student:
        qs = Course.objects.filter(
            enrollments__student=user, enrollments__is_active=True,
        ).distinct()
    else:
        qs = Course.objects.none()
    data = [
        {"code": c.code, "title": c.title, "slug": c.slug, "status": c.status}
        for c in qs.order_by("code")
    ]
    return JsonResponse({"count": len(data), "results": data})

@csrf_exempt
@require_safe
def api_assignments(request, course_slug: str):
    auth = _authenticate_api(request)
    if auth is None:
        return _api_error("Unauthorized", 401)
    user, scope = auth
    course = Course.objects.filter(slug=course_slug).first()
    if course is None:
        return _api_error("Not found", 404)
    # Same boundaries as the HTML view.
    from accounts.permissions import user_can_view_course

    if not user_can_view_course(user, course):
        return _api_error("Forbidden", 403)
    qs = course.assignments.all()
    if user.is_student:
        qs = qs.filter(status__in=[Assignment.Status.PUBLISHED, Assignment.Status.CLOSED])
    data = [
        {
            "id": a.id, "title": a.title, "status": a.status,
            "due_at": a.due_at.isoformat(), "max_score": a.max_score,
        }
        for a in qs.order_by("due_at")
    ]
    return JsonResponse({"count": len(data), "results": data})

@csrf_exempt
@require_safe
def api_my_grades(request):
    """A student-facing grade summary — only the caller's own released grades."""
    auth = _authenticate_api(request)
    if auth is None:
        return _api_error("Unauthorized", 401)
    user, scope = auth
    if not user.is_student:
        return _api_error("Forbidden", 403)
    qs = Submission.objects.filter(
        student=user, status=Submission.Status.RELEASED,
    ).select_related("assignment", "assignment__course")
    data = [
        {
            "course": s.assignment.course.code,
            "assignment": s.assignment.title,
            "score": str(s.final_score) if s.final_score is not None else None,
            "max_score": s.assignment.max_score,
            "released_at": s.released_at.isoformat() if s.released_at else None,
        }
        for s in qs
    ]
    log_action(actor=user, action="api.my_grades", request=request, metadata={"count": len(data)})
    return JsonResponse({"count": len(data), "results": data})

